#!/usr/bin/env python3
"""Offline report of actual production views; never redistributes user images."""
import base64,hashlib,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((R/p).read_text())
sha=lambda p:hashlib.sha256((R/p).read_bytes()).hexdigest()
esc=lambda s:html.escape(str(s),quote=True)
version=read('package.json')['version']
captures=read('artifacts/spa-monaco-captures/cameras.json')
notes={
 'la-source':('Reference 1 · image-8.png','Continuous outside paved escape and paved inner pit island; short red/yellow rounded apex/exit kerbs, narrow green edging and a moved outside perimeter.','Mapped racing/pit centrelines and legal road width are retained. Building massing, island shape and apron extents remain estimates.'),
 'les-combes':('Reference 2 · image-9.png','Independent right-hand T5 and left-hand T6 apexes; separate green-painted margins, paved strips and outside gravel instead of one kerb through the whole group.','The source view is not camera-calibrated. Kerb lengths, green widths and exact gravel boundaries are authored estimates.'),
 'malmedy':('Reference 2 · image-9.png','A separate right-hand T7 apex and left-side exit kerb, with its own green/gravel margin.','This is not a surveyed replacement of the mapped road. Trees, fencing and sign inventory remain simplified.'),
 'bus-stop':('References 3–4 · image-10.png / image-11.png','Short right-left apex windows, broad green/paved inside areas, a paved escape and diagonal white hatch markings.','Legal road/pit alignment is unchanged. Paddock furniture, exact painted polygons and wet surface appearance are not replicated precisely.'),
 'finish-straight':('References 3–4 · image-10.png / image-11.png','Green-edged paved shoulder and staggered starting-grid boxes approaching the existing start/finish timing line.','Timing-line position is unchanged. Garage architecture and sponsor gantry remain simplified original representations.'),
 'monaco-portal':('Reference 5 · image-12.png','A building-connected overhead portal, stacked facade/window bands and a retaining/podium wall on the hillside approach. The tunnel now visibly enters under a building.','Original mapped Fairmont outline/courtyards are retained where available; the short portal connection, podium treatment and architectural dimensions are estimated.'),
 'monaco-hotel':('Reference 5 · image-12.png','Explicit over-road upper-floor infill connects the previously separated hotel pieces. The existing 4.65 m tunnel ceiling and lighting remain below the hotel floor.','Modern Monaco is used for every era as requested. This is not a scanned hotel, surveyed street section or exact reconstruction of the photo’s race-year sponsor signs.'),
}
cards=[];manifest=[]
for c in captures:
 assert c['version']==version,(c['id'],c['version'],version)
 id=c['id'];p=f'artifacts/spa-monaco-captures/{id}.jpg';source,change,limit=notes[id]
 blob=(R/p).read_bytes();uri='data:image/jpeg;base64,'+base64.b64encode(blob).decode()
 cards.append(f'<article id="{id}" data-kind="{"spa"if c["track"]==0 else"monaco"}"><header><small>{esc(source)}</small><h2>{esc(c["title"])}</h2></header><img src="{uri}" alt="Actual game render: {esc(c["title"])}" loading="lazy"><div class="details"><p><b>CHANGED</b>{esc(change)}</p><p><b>LIMITS</b>{esc(limit)}</p></div><footer>Actual production render · high quality · 1000 × 625 · {esc(version)} · not camera-matched to the reference</footer></article>')
 manifest.append({**c,'sha256':hashlib.sha256(blob).hexdigest(),'bytes':len(blob)})
inputs=['web/track-finish.js','web/car-finish.js','web/season-liveries.js','data/liveries-2026.json','web/racing-path.js','web/racing-line.js','web/racing-guide.js','data/building-appearance.json','web/building-roofs.js','web/materials.js','data/corner-details.json','data/reference-scenes.json','data/spa-monaco-reference.json','web/graphics.js','web/corners.js','web/venue.js','web/reference-scene.js','src/corner.rs','src/venue.rs','src/reference_scene.rs']
(R/'data/spa-monaco-captures.json').write_text(json.dumps(dict(version=version,inputs={p:sha(p)for p in inputs},captures=manifest),indent=2)+'\n')
style='''*{box-sizing:border-box}body{margin:0;background:#10191c;color:#edf1eb;font:15px/1.75 system-ui,sans-serif}main{max-width:1130px;margin:auto;padding:30px 24px 70px}a{color:#b5d8c4}nav{display:flex;justify-content:space-between;border-bottom:1px solid #45534b;padding-bottom:18px;font-size:11px;letter-spacing:.1em}h1{font-size:clamp(42px,7vw,78px);letter-spacing:-.055em;line-height:1.08;margin:45px 0 22px}h1 span{color:#a7c9b5}.lead{max-width:950px;color:#bdccc3}.scope{padding:20px 24px;border:1px solid #405b4b;background:#1c2c24;border-left:4px solid #a7c9b5;margin:25px 0;font-size:13px}.scope strong{color:#d0e0d5}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:30px 0}button{border:1px solid #4e6557;border-radius:30px;background:#1b2a22;color:#dce7df;font:inherit;font-size:12px;padding:9px 18px;cursor:pointer}button[aria-pressed=true]{background:#b5cfbe;color:#16251c}article{background:#1a2420;border:1px solid #3e5145;border-radius:12px;overflow:hidden;margin:0 0 30px}header{padding:20px 25px}small{color:#aec5b6;font-size:10px;letter-spacing:.06em}h2{font-size:28px;line-height:1.3;margin:7px 0;letter-spacing:-.03em}img{width:100%;height:auto;display:block}.details{display:grid;grid-template-columns:1fr 1fr;gap:28px;padding:22px 25px}.details p{margin:0;font-size:13px;color:#c5d3ca}.details b{display:block;color:#a8ccb5;font-size:10px;letter-spacing:.12em;margin-bottom:7px}.details p:last-child b{color:#d0bd91}article footer{font-size:10px;color:#9fb4a6;padding:0 25px 20px}.notes{font-size:12px;color:#a7bcb0}.hidden{display:none}@media(max-width:650px){main{padding:24px 14px}.details{grid-template-columns:1fr;gap:18px}header,.details{padding:18px}h2{font-size:24px}nav{font-size:9px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APEX / HERITAGE — Spa corners & Monaco tunnel</title><style>{style}</style></head><body><main><nav><b>APEX / HERITAGE</b><span>REFERENCE FOLLOW-UP · {version}</span></nav><h1>Spa, corner by corner.<br><span>Monaco, under the hotel.</span></h1><p class="lead">Seven actual game views showing the changes guided by your five supplied references. These are production captures, not concept art or generated replacement photographs.</p><div class="scope"><strong>Spa:</strong> recent surface and its labelled 2021 substitute only. The older three surface profiles remain byte-identical; the existing all-era Eau Rouge treatment is preserved.<br><strong>Monaco:</strong> the modern hotel/tunnel treatment is shared by every era as previously requested. Explicit overhead geometry preserves vehicle clearance; the ordinary ground-building road exclusion stays enabled.</div><div class="filters"><button data-kind="all" aria-pressed="true">All seven views</button><button data-kind="spa" aria-pressed="false">Spa · five views</button><button data-kind="monaco" aria-pressed="false">Monaco · two views</button></div>{''.join(cards)}<section class="notes"><b>Reference rights and accuracy.</b> Your source images are reference-only: their original rights/dates are not independently established, so no user image pixels are redistributed here or in the game. Reference 1 looks like a game render, not survey evidence. This page embeds only original game screenshots. Underlying mapped features © OpenStreetMap contributors, ODbL 1.0; editable geometry, provenance and limits remain in the source notices.<br><br><a href="https://the-crab-post-office.github.io/apex-heritage/">Play the game ↗</a> · <a href="https://the-crab-post-office.github.io/apex-heritage/photo-accuracy.html">Broader all-track/all-era photo audit ↗</a> · <a href="https://github.com/the-crab-post-office/apex-heritage">Source and capture checksums ↗</a></section></main><script>for(const button of document.querySelectorAll('button[data-kind]'))button.onclick=()=>{{for(const b of document.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b===button));for(const card of document.querySelectorAll('article'))card.classList.toggle('hidden',button.dataset.kind!=='all'&&card.dataset.kind!==button.dataset.kind);}};</script></body></html>'''
(R/'web/public/spa-monaco-update.html').write_text(page)
print('Built spa-monaco-update.html:',len(page.encode()),'bytes;',len(captures),'actual production views')
